class Store
{
    int nuts;
    public void Add(int n)
    {
        if (n < 0) throw new ArgumentException("cannot add a negative number");
        nuts += n;
    }
    public void Take(int n)
    {
        if (n > nuts) throw new InvalidOperationException($"only {nuts} nuts stored");
        nuts -= n;
    }
}

