static T Largest<T>(List<T> items) where T : IComparable<T>
{
    T best = items[0];
    foreach (var item in items)
    {
        if (item.CompareTo(best) > 0) best = item;
    }
    return best;
}

record Pair<A, B>(A First, B Second);

