static IEnumerable<int> Countdown(int from)
{
    for (int i = from; i > 0; i--) yield return i;
    yield return 0;
}

static IEnumerable<long> Fibonacci()
{
    long a = 0, b = 1;
    while (true)
    {
        yield return a;
        (a, b) = (b, a + b);
    }
}

